package com.vuelossanitarios.backend.service;
import com.vuelossanitarios.backend.api.ApiException;import com.vuelossanitarios.backend.api.dto.NotificationDtos.*;import com.vuelossanitarios.backend.domain.flight.Flight;import com.vuelossanitarios.backend.domain.notification.Notification;import com.vuelossanitarios.backend.domain.user.User;import com.vuelossanitarios.backend.repository.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class NotificationService {private final NotificationRepository notifications;private final UserRepository users;public NotificationService(NotificationRepository n,UserRepository u){notifications=n;users=u;}@Transactional public void create(User recipient,Flight flight,String type,String message){Notification n=new Notification();n.setUser(recipient);n.setFlight(flight);n.setTipo(type);n.setMensaje(message);notifications.save(n);}@Transactional(readOnly=true) public NotificationPage list(UUID user,int page,int size){Page<Notification> result=notifications.findByUserIdOrderByCreatedAtDesc(user,PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size))));return new NotificationPage(result.getContent().stream().map(this::view).toList(),notifications.countByUserIdAndLeidoFalse(user),result.getTotalElements());}@Transactional public void read(UUID id,UUID user){Notification n=notifications.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Notificación inexistente"));if(!n.getUser().getId().equals(user))throw new ApiException(HttpStatus.FORBIDDEN,"Notificación ajena");n.setLeido(true);}@Transactional public int readAll(UUID user){return notifications.markAllRead(user);}private NotificationView view(Notification n){return new NotificationView(n.getId(),n.getFlight()==null?null:n.getFlight().getId(),n.getTipo(),n.getMensaje(),n.getLeido(),n.getCreatedAt());}}
